 static Field field(Class<?>cls,String name)throws Exception {Field f=cls.getDeclaredField(name);f.setAccessible(true);return f;}
 public static void main(String[] args)throws Exception{Bootstrap.register();FMLCommonHandler.instance().beginLoading(net.minecraftforge.fml.server.FMLServerHandler.instance());ModMetadata md=new ModMetadata();md.modId="hbm";md.name="Ore native callback probe";md.version="1";DummyModContainer c=new DummyModContainer(md);Loader.instance().setupTestHarness(c);Loader.instance().setActiveModContainer(c);

 FenceConstruction.initialize();Block b=ModBlocks.fence_metal;b.setRegistryName("hbm","tile.fence_metal");ForgeRegistries.BLOCKS.register(b);ForgeRegistries.ITEMS.register(new com.hbm.items.block.ItemBlockBase(b).setRegistryName(b.getRegistryName()));ModBlocks.fence_gate=new Block(Material.IRON);runOwner(b);System.out.println("PASS "+checks+" native fence owner/WorldChunk/drop/save checks");}
 static void runOwner(Block b)throws Exception {
  check(b.getClass()==BlockMetalFence.class,"actual exact constructor owner");check(b.getBlockState().getValidStates().size()==256,"16 metadata by16 connections");check(b.getMetaFromState(b.getDefaultState())==0,"default zero");NativeWorld w=new NativeWorld();
  check(b.getDefaultState().getMaterial()==Material.IRON&&b.getBlockHardness(b.getDefaultState(),w,BlockPos.ORIGIN)==15&&b.getExplosionResistance(null)==.15F,"exact owner material/hardness/resistance");
  for(int meta=0;meta<16;meta++){IBlockState s=b.getStateFromMeta(meta);BlockPos p=new BlockPos(8,96+meta,8);check(b.getMetaFromState(s)==meta&&Block.getStateById(Block.getStateId(s))==s,"native metadata/state IDs");check(w.setBlockState(p,s,3)&&w.getBlockState(p)==s,"actual native placement");check(!b.hasTileEntity(s)&&b.createTileEntity(w,s)==null&&w.getTileEntity(p)==null,"no tile lifecycle");NonNullList<ItemStack> drops=NonNullList.create();b.getDrops(drops,w,p,s,3);check(drops.size()==1&&drops.get(0).getItem()==Item.getItemFromBlock(b)&&drops.get(0).getCount()==1&&drops.get(0).getItemDamage()==meta%2,"actual native Block drops rectify modulo2");}
  ItemBlock item=(ItemBlock)Item.getItemFromBlock(b);BlockPos placed=new BlockPos(3,80,3);for(int m=0;m<16;m++){w.setBlockToAir(placed);ItemStack stack=new ItemStack(item,1,m);IBlockState state=b.getStateForPlacement(w,placed,EnumFacing.UP,.5F,.5F,.5F,item.getMetadata(m),null,EnumHand.MAIN_HAND);check(item.placeBlockAt(stack,null,w,placed,EnumFacing.UP,.5F,.5F,.5F,state)&&b.getMetaFromState(w.getBlockState(placed))==m,"actual ItemBlockBase placement and state dispatch");}
  NonNullList<ItemStack> creative=NonNullList.create();Item.getItemFromBlock(b).getSubItems(CreativeTabs.SEARCH,creative);check(creative.size()==2&&creative.get(0).getItemDamage()==0&&creative.get(1).getItemDamage()==1,"actual ItemBlockBase creative dispatch");
  net.minecraft.world.chunk.storage.AnvilChunkLoader loader=new net.minecraft.world.chunk.storage.AnvilChunkLoader(new File("chunk-storage"),new net.minecraft.util.datafix.DataFixer(1343));Method write=loader.getClass().getDeclaredMethod("writeChunkToNBT",Chunk.class,World.class,NBTTagCompound.class),read=loader.getClass().getDeclaredMethod("readChunkFromNBT",World.class,NBTTagCompound.class);write.setAccessible(true);read.setAccessible(true);NBTTagCompound saved=new NBTTagCompound();write.invoke(loader,w.getChunk(0,0),w,saved);ByteArrayOutputStream bytes=new ByteArrayOutputStream();CompressedStreamTools.writeCompressed(saved,bytes);NBTTagCompound restored=CompressedStreamTools.readCompressed(new ByteArrayInputStream(bytes.toByteArray()));NativeWorld fresh=new NativeWorld();Chunk loaded=(Chunk)read.invoke(loader,fresh,restored);fresh.chunks.put(NativeWorld.key(0,0),loaded);loaded.markLoaded(true);
  for(int m=0;m<16;m++){BlockPos p=new BlockPos(8,96+m,8);check(fresh.getBlockState(p)==b.getStateFromMeta(m)&&fresh.getTileEntity(p)==null,"compressed native Anvil state/tile roundtrip");fresh.spawned.clear();check(fresh.destroyBlock(p,true)&&fresh.isAirBlock(p),"actual native destruction");check(fresh.spawned.size()==1&&fresh.spawned.get(0).getItem()==Item.getItemFromBlock(b)&&fresh.spawned.get(0).getItemDamage()==m%2,"actual native EntityItem drop");}
  BlockPos p=new BlockPos(4,75,4);BlockMetalFence fence=(BlockMetalFence)b;Block[] neighbors={b,net.minecraft.init.Blocks.OAK_FENCE_GATE,ModBlocks.fence_gate,net.minecraft.init.Blocks.STONE,net.minecraft.init.Blocks.PUMPKIN,net.minecraft.init.Blocks.GLASS,net.minecraft.init.Blocks.OAK_FENCE,net.minecraft.init.Blocks.SPRUCE_FENCE_GATE,net.minecraft.init.Blocks.AIR};boolean[] expected={true,true,true,true,false,false,false,false,false};
  for(int i=0;i<neighbors.length;i++){w.setBlockState(p.north(),neighbors[i].getDefaultState(),3);check(fence.canConnectTo(w,p.north(),EnumFacing.SOUTH)==expected[i]&&fence.getActualState(b.getDefaultState(),w,p).getValue(net.minecraft.block.BlockFence.NORTH)==expected[i],"corrected custom native connection predicate, not vanilla fallback");}
  for(int mask=0;mask<16;mask++){for(int i=0;i<4;i++)w.setBlockState(p.offset(new EnumFacing[]{EnumFacing.NORTH,EnumFacing.SOUTH,EnumFacing.WEST,EnumFacing.EAST}[i]),(mask&(1<<i))!=0?net.minecraft.init.Blocks.STONE.getDefaultState():net.minecraft.init.Blocks.AIR.getDefaultState(),3);List<net.minecraft.util.math.AxisAlignedBB> boxes=new ArrayList<>();fence.addCollisionBoxToList(b.getDefaultState(),w,p,new net.minecraft.util.math.AxisAlignedBB(0,0,0,16,256,16),boxes,null,false);check(!boxes.isEmpty(),"real collision list");for(net.minecraft.util.math.AxisAlignedBB box:boxes)check(box.maxY==p.getY()+1,"corrected original height1 not vanilla1.5");}
 }
